/* CS Quest: every word of this game in one language. */
(window.CsqPacks = window.CsqPacks || {})["robo-route"] = Object.assign(window.CsqPacks["robo-route"] || {}, { "nl": {"strings":{"1":"1","2":"2","4":"4","5":"5","6":"6","8":"8","9":"9","10":"10","Snap blocks together and drive Bolt the robot to the goal!":"Klik blokken aan elkaar en rijd robot Bolt naar het doel!","Pick a chapter":"Kies een hoofdstuk","Grade band":"Groepsniveau","{band} band":"Niveau {band}","Quest Card":"Questkaart","{done}/{total} levels":"{done}/{total} levels","{n} stars":{"one":"{n} ster","other":"{n} sterren"},"{chapter} · Level {n}":"{chapter} · Level {n}","Class quest: {chapter} · {band}":"Klassenquest: {chapter} · {band}","The board: {w} by {h} squares":"Het speelveld: {w} bij {h} vakjes","{name} is {value}":"{name} is {value}","Put the plan lines in order first.":"Zet eerst de regels van het plan in de goede volgorde.","Added {block}":"{block} toegevoegd","{a} {op} {b}":"{a} {op} {b}","not {x}":"niet {x}","repeat until {x}":"herhaal tot {x}","repeat {n} times":{"one":"herhaal {n} keer","other":"herhaal {n} keer"},"if {c}":"als {c}","when {e}":"wanneer {e}","set {v} to {x}":"zet {v} op {x}","change {v} by {n}":"verander {v} met {n}","My Block {name}":"Mijn blok {name}","call {name}":"roep {name} aan","Tap a block on the shelf to start your program.":"Tik op een blok in de kast om je programma te beginnen.","start here":"begin hier","Put the next block here":"Zet het volgende blok hier","inside":"binnen","else":"anders","end":"einde","Move up":"Omhoog","Move down":"Omlaag","Delete block":"Blok verwijderen","Change":"Wijzigen","Move into the block above":"In het blok erboven","Move out of its block":"Uit zijn blok halen","Add else":"Anders toevoegen","Done":"Klaar","Less":"Minder","More":"Meer","How many times?":"Hoe vaak?","a box":"een doos","on":"aan","off":"uit","not":"niet","Step":"Stap","Reset":"Opnieuw","Hint":"Hint","Learn":"Leren","Skip level":"Level overslaan","Chapter map":"Hoofdstukkaart","The program is empty. Tap a block on the shelf.":"Het programma is leeg. Tik op een blok in de kast.","Board {n} of {total}":"Speelveld {n} van {total}","Bump! A wall after step {n}.":"Boem! Een muur na stap {n}.","Splash!":"Plons!","Nothing to pick up here.":"Hier valt niets op te pakken.","Not yet.":"Nog niet.","Hints are open now.":"De hints zijn nu open.","Bolt made it!":"Bolt heeft het gehaald!","Level {n} done!":"Level {n} klaar!","Level skipped":"Level overgeslagen","{chapter} complete!":"{chapter} voltooid!","Quest complete!":"Quest voltooid!","Great work. Tell your teacher you finished, or play the chapter again for more stars.":"Goed gedaan. Vertel je leraar dat je klaar bent, of speel het hoofdstuk nog eens voor meer sterren.","Let's go!":"Daar gaan we!","Plan first":"Eerst plannen","Tap the plan lines in the order Bolt should do them. Then the shelf opens.":"Tik de regels van het plan aan in de volgorde waarin Bolt ze moet doen. Dan gaat de kast open.","The shelf is open.":"De kast is open.","Run your program first. Hints open after a try.":"Start eerst je programma. De hints gaan open na één poging.","Hint {n} of 3":"Hint {n} van 3","This hint shows a move, so the third star stays in the box this time.":"Deze hint laat een zet zien, dus de derde ster blijft deze keer in de doos.","Got it":"Begrepen","Case closed?":"Zaak gesloten?","How sure were you?":"Hoe zeker was je?","Not yet":"Nog niet","Getting it":"Bijna","Got it!":"Begrepen!","Read aloud":"Voorlezen","Sound and more":"Geluid en meer","Enter a quest code":"Questcode invoeren","Delete":"Wissen","Go":"Ga","Four digits, please.":"Vier cijfers, graag.","Close":"Sluiten","No chapter has that number yet.":"Geen enkel hoofdstuk heeft dat nummer.","Sequences":"Reeksen","Loops":"Lussen","Conditionals & events":"Voorwaarden en gebeurtenissen","Variables":"Variabelen","Functions":"Functies","Debug Lab":"Foutenlab","Best Route":"De beste route","Level Maker":"Levelbouwer","move":"vooruit","turn left":"draai links","turn right":"draai rechts","pick up":"oppakken","drop":"neerleggen","repeat":"herhaal","repeat until goal":"herhaal tot doel","if":"als","if / else":"als / anders","when":"wanneer","set":"zet","change by":"verander met","My Block":"Mijn blok","call":"roep aan","path ahead":"pad vrij","wall ahead":"muur vooruit","on a gem":"op een edelsteen","something to pick up":"iets om op te pakken","on paint":"op verf","I have the key":"ik heb de sleutel","on the button":"op de knop","on the goal":"op het doel","a gem is picked up":"een edelsteen is opgepakt","Bolt bumps":"Bolt botst","the button is pressed":"de knop is ingedrukt","red":"rood","blue":"blauw","green":"groen","yellow":"geel","and":"en","or":"of","Explorer":"Ontdekker","Pro":"Pro","An algorithm is a list of steps in order":"Een algoritme is een lijst stappen in volgorde","Bolt does exactly what the blocks say, one after another, from the top. Tap a block on the shelf to add it to the program, then press Run.":"Bolt doet precies wat de blokken zeggen, de een na de ander, van boven naar beneden. Tik op een blok in de kast om het in het programma te zetten en druk dan op Start.","Bolt runs the blocks...":"Bolt voert de blokken uit...","in order, from the top":"op volgorde, van boven af","all at the same time":"allemaal tegelijk","in any order it likes":"in elke volgorde die hij wil","Does a turn block move Bolt forward?":"Gaat Bolt met een draaiblok vooruit?","A turn spins Bolt on the spot. After the turn, Bolt still needs move blocks.":"Draaien laat Bolt op zijn plek draaien. Na het draaien heeft Bolt nog vooruit-blokken nodig.","What does turn left do?":"Wat doet draai links?","Bolt spins to face left and stays on its square":"Bolt draait naar links en blijft op zijn vakje","Bolt moves one square to the left":"Bolt gaat één vakje naar links","Bolt goes back to the start":"Bolt gaat terug naar de start","Stand on the gem, then pick it up. Bolt only picks up what is under it.":"Ga op de edelsteen staan en pak hem dan op. Bolt pakt alleen op wat onder hem ligt.","Where does Bolt have to be when it picks up the gem?":"Waar moet Bolt staan als hij de edelsteen oppakt?","Pick up works only on the square Bolt is standing on.":"Oppakken werkt alleen op het vakje waar Bolt staat.","When does pick up work?":"Wanneer werkt oppakken?","When Bolt stands on the gem":"Als Bolt op de edelsteen staat","When Bolt is next to the gem":"Als Bolt naast de edelsteen staat","Any time":"Altijd","Plan first, then program":"Eerst plannen, dan programmeren","Pro programmers write the plan in plain words before they touch the blocks: this is called pseudocode. Put the plan lines in order and the shelf opens.":"Echte programmeurs schrijven het plan in gewone woorden op voordat ze de blokken aanraken: dat heet pseudocode. Zet de regels van het plan op volgorde en de kast gaat open.","Which plan line comes first?":"Welke regel van het plan komt eerst?","Each plan line becomes a run of blocks. Finish one line before you start the next.":"Elke regel van het plan wordt een rij blokken. Maak één regel af voordat je aan de volgende begint.","Pseudocode is...":"Pseudocode is...","the plan in plain words":"het plan in gewone woorden","a secret robot language":"een geheime robottaal","the fastest route":"de snelste route","Drive to the first gem and pick it up":"Rijd naar de eerste edelsteen en pak hem op","Turn and drive up to the second gem":"Draai en rijd omhoog naar de tweede edelsteen","Turn toward the goal and drive there":"Draai naar het doel en rijd erheen","Which squares are water? Bolt cannot swim.":"Welke vakjes zijn water? Bolt kan niet zwemmen.","Only one square leads into the flag without a splash: the one below it.":"Maar één vakje leidt zonder plons naar de vlag: het vakje eronder.","A program is a set of...":"Een programma is een rij...","exact steps for the computer":"precieze stappen voor de computer","ideas the computer guesses from":"ideeën waaruit de computer raadt","pictures":"plaatjes","How many squares is each leg of the plan?":"Hoeveel vakjes is elk stuk van het plan?","Count each straight run before you add its moves. Water is a splash.":"Tel elk recht stuk voordat je de zetten toevoegt. Water betekent plons.","Why write the plan first?":"Waarom schrijf je eerst het plan?","It splits a long job into parts you can check":"Het verdeelt een lange klus in stukken die je kunt controleren","It makes Bolt faster":"Het maakt Bolt sneller","Bolt reads the plan":"Bolt leest het plan","Drive east along the top":"Rijd bovenlangs naar het oosten","Go down and pick up the gem":"Ga naar beneden en pak de edelsteen op","There are two ways to the flag. Which one has fewer steps?":"Er zijn twee wegen naar de vlag. Welke heeft minder stappen?","Going down the left side first is shorter than going along the top.":"Eerst langs de linkerkant naar beneden is korter dan bovenlangs.","Two programs both reach the flag. Which is better?":"Twee programma's halen allebei de vlag. Welke is beter?","The one with fewer steps that still works":"Die met minder stappen die toch werkt","The one with more blocks":"Die met meer blokken","They are always the same":"Ze zijn altijd hetzelfde","Count the steps of both routes before you choose.":"Tel de stappen van beide routes voordat je kiest.","The route along the top needs four turns; the route down the left needs one.":"De route bovenlangs heeft vier bochten nodig; de route links naar beneden maar één.","Compare the two routes":"Vergelijk de twee routes","Pick the shorter one":"Kies de kortste","Program it":"Programmeer hem","This route has three legs. What is the first leg?":"Deze route heeft drie stukken. Wat is het eerste stuk?","Leg 1: along the top to the corner. Leg 2: down. Leg 3: back along the middle to the flag.":"Stuk 1: bovenlangs naar de hoek. Stuk 2: naar beneden. Stuk 3: door het midden terug naar de vlag.","Splitting a long route into legs helps because...":"Een lange route in stukken verdelen helpt, omdat...","you can check each small part":"je elk klein stuk kunt controleren","Bolt moves faster":"Bolt sneller rijdt","it uses fewer gems":"het minder edelstenen kost","Name the three legs before you build.":"Geef de drie stukken een naam voordat je bouwt.","Each leg ends with a turn. Count the squares of each leg.":"Elk stuk eindigt met een bocht. Tel de vakjes van elk stuk.","Leg 1: east along the top, pick up the gem":"Stuk 1: bovenlangs naar het oosten, pak de edelsteen","Leg 2: turn and go down":"Stuk 2: draai en ga naar beneden","Leg 3: turn and go west to the goal, picking up the gem":"Stuk 3: draai en ga naar het westen naar het doel, en pak onderweg de edelsteen","A loop repeats steps":"Een lus herhaalt stappen","Writing move five times is boring. A repeat block runs the blocks inside it again and again. The number says how many times.":"Vijf keer vooruit schrijven is saai. Een herhaal-blok voert de blokken erin steeds opnieuw uit. Het getal zegt hoe vaak.","How many times does the move block need to run?":"Hoe vaak moet het vooruit-blok uitgevoerd worden?","Put one move block inside the repeat and set its number to the number of squares.":"Zet één vooruit-blok in de herhaal en stel het getal in op het aantal vakjes.","The number on a repeat block means...":"Het getal op een herhaal-blok betekent...","how many times the blocks inside run":"hoe vaak de blokken erin worden uitgevoerd","how many squares Bolt moves in one step":"hoeveel vakjes Bolt in één stap gaat","how many blocks you may use":"hoeveel blokken je mag gebruiken","Which steps happen again and again on these stairs?":"Welke stappen komen op deze trap steeds terug?","One stair is: move, turn right, move, turn left. The staircase is that stair three times.":"Eén tree is: vooruit, draai rechts, vooruit, draai links. De trap is die tree drie keer.","What goes inside a repeat block?":"Wat gaat er in een herhaal-blok?","The steps that happen again and again":"De stappen die steeds terugkomen","Only one move block":"Maar één vooruit-blok","The goal":"Het doel","Bolt goes round three sides of a square. What repeats?":"Bolt rijdt langs drie zijden van een vierkant. Wat herhaalt zich?","Each side is three moves and a turn right.":"Elke zijde is drie keer vooruit en één keer draai rechts.","Look at the gems. Is there a pattern?":"Kijk naar de edelstenen. Zie je een patroon?","Every gem is two squares apart: move, move, pick.":"Elke edelsteen ligt twee vakjes verder: vooruit, vooruit, oppakken.","Bolt picks up a gem on every second square. A good loop body is...":"Bolt pakt op elk tweede vakje een edelsteen op. Een goede inhoud voor de lus is...","move, move, pick":"vooruit, vooruit, oppakken","pick, pick":"oppakken, oppakken","Four gems in a row: what two blocks repeat?":"Vier edelstenen op een rij: welke twee blokken herhalen zich?","Move then pick, four times. After the loop, Bolt still needs to turn and go up.":"Vooruit en dan oppakken, vier keer. Na de lus moet Bolt nog draaien en omhoog gaan.","Repeat 4 with move and pick inside picks up...":"Herhaal 4 met vooruit en oppakken erin pakt op...","4 gems":"4 edelstenen","2 gems":"2 edelstenen","8 gems":"8 edelstenen","The loop will say repeat 4 with move and pick inside. How many gems will Bolt pick up?":"De lus wordt herhaal 4 met vooruit en oppakken erin. Hoeveel edelstenen pakt Bolt op?","Five gems in a row: what two blocks repeat?":"Vijf edelstenen op een rij: welke twee blokken herhalen zich?","Move then pick, five times. Then one more move before the turn.":"Vooruit en dan oppakken, vijf keer. Dan nog één keer vooruit voor de bocht.","Repeat 5 with move and pick inside: how many move steps run?":"Herhaal 5 met vooruit en oppakken erin: hoeveel stappen vooruit worden gezet?","Bolt drives round the room. Which steps come again?":"Bolt rijdt de kamer rond. Welke stappen komen terug?","Each side is three moves, a pick and a turn right. The last side has no gem.":"Elke zijde is drie keer vooruit, één keer oppakken en draai rechts. De laatste zijde heeft geen edelsteen.","After a loop ends, Bolt...":"Als een lus klaar is, gaat Bolt...","carries on with the blocks after the loop":"verder met de blokken na de lus","goes back to the start":"terug naar de start","stops for good":"voorgoed stoppen","The path zigzags. What is one zig?":"Het pad gaat zigzag. Wat is één zig?","One zig is: move, move, turn right, move, turn left.":"Eén zig is: vooruit, vooruit, draai rechts, vooruit, draai links.","The repeat count is how many times...":"Het herhaalgetal zegt hoe vaak...","the whole bracket runs":"het hele blok wordt uitgevoerd","Bolt turns":"Bolt draait","you tap Run":"je op Start tikt","A long staircase. How many stairs?":"Een lange trap. Hoeveel treden?","One stair: move, turn right, move, turn left. Count the stairs for the repeat number.":"Eén tree: vooruit, draai rechts, vooruit, draai links. Tel de treden voor het herhaalgetal.","A loop saved you blocks because...":"Een lus heeft je blokken bespaard, omdat...","the same steps were written once and run many times":"dezelfde stappen één keer zijn geschreven en vaak zijn uitgevoerd","Bolt skipped squares":"Bolt vakjes heeft overgeslagen","turns are free":"bochten gratis zijn","A loop inside a loop":"Een lus in een lus","The inner loop makes one stair. The outer loop makes the staircase. To know how many moves really ran, multiply: 3 stairs with 2 moves each is 6 moves.":"De binnenste lus maakt één tree. De buitenste lus maakt de trap. Wil je weten hoeveel zetten er echt zijn gedaan, vermenigvuldig dan: 3 treden met elk 2 zetten is 6 zetten.","Each stair goes up two, then across one. Can a loop make the up part?":"Elke tree gaat twee omhoog en dan één opzij. Kan een lus het stuk omhoog doen?","Put repeat 2 with a move inside the outer repeat. Then turn right, move, turn left.":"Zet herhaal 2 met een vooruit in de buitenste herhaal. Dan draai rechts, vooruit, draai links.","Repeat 3 with repeat 2 with move inside: how many moves run?":"Herhaal 3 met herhaal 2 met vooruit erin: hoeveel zetten worden gedaan?","Two rows of gems. What does Bolt do for one row?":"Twee rijen edelstenen. Wat doet Bolt voor één rij?","One row: pick three gems, turn and come back, then step down. The outer loop does that for both rows.":"Eén rij: drie edelstenen oppakken, omdraaien en terugrijden, dan één vakje naar beneden. De buitenste lus doet dat voor beide rijen.","In a nested loop, the inner loop...":"In een geneste lus wordt de binnenste lus...","runs completely every time the outer loop runs once":"helemaal uitgevoerd, elke keer dat de buitenste lus één keer rondgaat","runs only once":"maar één keer uitgevoerd","runs after the outer loop ends":"uitgevoerd nadat de buitenste lus klaar is","Each stair has two gems going up.":"Elke tree heeft twee edelstenen op weg omhoog.","The inner loop climbs and picks twice; the outer loop makes three stairs.":"De binnenste lus klimt en pakt twee keer op; de buitenste lus maakt drie treden.","Repeat 3 with repeat 2 with move and pick inside picks up...":"Herhaal 3 met herhaal 2 met vooruit en oppakken erin pakt op...","6 gems":"6 edelstenen","5 gems":"5 edelstenen","3 gems":"3 edelstenen","Par challenge: six blocks or fewer. Bolt goes round a square of three.":"Par-uitdaging: zes blokken of minder. Bolt rijdt rond een vierkant van drie.","Three sides are the same: repeat 3 with move inside, then turn right. The last side is shorter.":"Drie zijden zijn gelijk: herhaal 3 met vooruit erin, dan draai rechts. De laatste zijde is korter.","Which program is shortest for three equal sides and one short side?":"Welk programma is het kortst voor drie gelijke zijden en één korte?","A loop of loops, then a small loop":"Een lus van lussen, dan een kleine lus","Twelve move blocks":"Twaalf vooruit-blokken","One big repeat 12":"Eén grote herhaal 12","A conditional chooses":"Een voorwaarde kiest","What should Bolt do when the path ahead is blocked?":"Wat moet Bolt doen als het pad vooruit geblokkeerd is?","Inside the loop: if path ahead, move; else, turn left.":"In de lus: als pad vrij, vooruit; anders draai links.","An if block...":"Een als-blok...","checks a condition and chooses what to run":"controleert een voorwaarde en kiest wat er gebeurt","repeats blocks":"herhaalt blokken","moves Bolt":"beweegt Bolt","An event starts a piece of program":"Een gebeurtenis start een stukje programma","A when block waits for something to happen in the world. When Bolt picks up a gem, the blocks inside run right then. An if asks; a when listens.":"Een wanneer-blok wacht tot er iets gebeurt in de wereld. Wanneer Bolt een edelsteen oppakt, gaan de blokken erin meteen aan de slag. Een als vraagt; een wanneer luistert.","Every gem sits on a corner. What should happen when Bolt picks one up?":"Elke edelsteen ligt op een hoek. Wat moet er gebeuren als Bolt er een oppakt?","A when gem block with turn right inside. The loop keeps moving and picking.":"Een blok wanneer een edelsteen is opgepakt met draai rechts erin. De lus blijft vooruit gaan en oppakken.","What is the difference between if and when?":"Wat is het verschil tussen als en wanneer?","If asks a question now; when waits for something to happen":"Als stelt nu een vraag; wanneer wacht tot er iets gebeurt","They are the same":"Ze zijn hetzelfde","When is for turning only":"Wanneer is alleen om te draaien","The corner is in a different place each time. Can Bolt feel it?":"De hoek ligt elke keer ergens anders. Kan Bolt hem voelen?","Repeat until goal. Inside: if path ahead move, else turn left.":"Herhaal tot doel. Erin: als pad vrij vooruit, anders draai links.","Why did a fixed list of moves fail on one of the boards?":"Waarom ging een vaste lijst zetten mis op een van de speelvelden?","The corner moved, and the list could not notice":"De hoek was verschoven, en de lijst kon dat niet merken","Bolt was too slow":"Bolt was te langzaam","The goal disappeared":"Het doel was verdwenen","The paint marks the corners. What should Bolt do on paint?":"De verf markeert de hoeken. Wat moet Bolt op verf doen?","Move, then: if on paint, turn right. Keep going until the goal.":"Vooruit, dan: als op verf, draai rechts. Ga door tot het doel.","On every loop turn, the if block...":"Bij elke ronde van de lus controleert het als-blok...","checks the paint again":"de verf opnieuw","checks only the first time":"alleen de eerste keer","never checks":"nooit","Bolt is going to bump. Can a bump be useful?":"Bolt gaat zo botsen. Kan botsen handig zijn?","A when bump block with turn left inside. Then just keep moving until the goal.":"Een blok wanneer Bolt botst met draai links erin. Rijd daarna gewoon vooruit tot het doel.","A when bump block runs...":"Een blok wanneer Bolt botst wordt uitgevoerd...","each time Bolt bumps into something":"elke keer dat Bolt ergens tegenaan botst","once at the start":"één keer aan het begin","when you press Run":"als je op Start drukt","The gems are on different squares each time. When should Bolt pick?":"De edelstenen liggen elke keer op andere vakjes. Wanneer moet Bolt oppakken?","Only pick when there is a gem: if on a gem, pick. Then move.":"Pak alleen op als er een edelsteen ligt: als op een edelsteen, oppakken. Dan vooruit.","Pick up with no gem under Bolt is...":"Oppakken zonder edelsteen onder Bolt is...","a mistake: check first with if":"een fout: controleer eerst met als","fine":"prima","a way to find gems":"een manier om edelstenen te vinden","One program for three different mazes. What is the rule at every wall?":"Eén programma voor drie verschillende doolhoven. Wat is de regel bij elke muur?","If the path ahead is clear, move. Else, turn right. Until the goal.":"Als het pad vooruit vrij is, vooruit. Anders draai rechts. Tot het doel.","One program solved three mazes because...":"Eén programma loste drie doolhoven op, omdat...","it checked the wall every step instead of counting":"het bij elke stap de muur controleerde in plaats van te tellen","the mazes were the same":"de doolhoven hetzelfde waren","it was long":"het lang was","AND, OR and NOT":"EN, OF en NIET","Two questions can be joined. Wall ahead AND on a gem is true only when both are true. Wall OR paint is true when either is. NOT flips an answer.":"Twee vragen kun je samenvoegen. Muur vooruit EN op een edelsteen is alleen waar als allebei waar zijn. Muur OF verf is waar als een van de twee waar is. NIET draait een antwoord om.","A gem on a corner means turn right. A bare corner means turn left. How does Bolt tell them apart?":"Een edelsteen op een hoek betekent draai rechts. Een lege hoek betekent draai links. Hoe ziet Bolt het verschil?","If wall ahead AND on a gem: pick, turn right. Else if wall ahead: turn left. Else: move.":"Als muur vooruit EN op een edelsteen: oppakken, draai rechts. Anders als muur vooruit: draai links. Anders: vooruit.","Wall ahead AND on a gem is true when...":"Muur vooruit EN op een edelsteen is waar als...","both are true":"allebei waar zijn","either one is true":"een van de twee waar is","neither is true":"geen van beide waar is","Some corners have a wall, some have paint. Bolt turns right at both.":"Sommige hoeken hebben een muur, andere verf. Bolt draait bij allebei naar rechts.","Move first. Then: if NOT path ahead OR on paint, turn right.":"Eerst vooruit. Dan: als NIET pad vrij OF op verf, draai rechts.","NOT path ahead OR on paint is true when...":"NIET pad vrij OF op verf is waar als...","the way is blocked, or Bolt stands on paint, or both":"de weg versperd is, of Bolt op verf staat, of allebei","only when both happen":"alleen als allebei gebeuren","never":"nooit","One program, three mazes. What is the rule at every wall?":"Eén programma, drie doolhoven. Wat is de regel bij elke muur?","Put the if inside the loop so it is checked at every step.":"Zet de als in de lus, zodat hij bij elke stap wordt gecontroleerd.","An if inside a loop is checked...":"Een als in een lus wordt gecontroleerd...","every time round the loop":"bij elke ronde van de lus","only once":"maar één keer","at the end":"aan het eind","The door needs the key, and the key is somewhere on the way.":"De deur heeft de sleutel nodig, en de sleutel ligt ergens onderweg.","If there is something to pick up, pick it. Then the usual: if path move, else turn right.":"Als er iets om op te pakken is, pak het op. Dan zoals altijd: als pad vrij vooruit, anders draai rechts.","The door opened because...":"De deur ging open, omdat...","Bolt had picked up the key before reaching it":"Bolt de sleutel had opgepakt voordat hij er was","Bolt bumped it":"Bolt ertegenaan botste","doors always open":"deuren altijd opengaan","A variable is a labeled box":"Een variabele is een doos met een label","How will Bolt know it has five gems?":"Hoe weet Bolt dat hij vijf edelstenen heeft?","Set count to 0 first. Each time Bolt picks a gem, change count by 1.":"Zet count eerst op 0. Elke keer dat Bolt een edelsteen oppakt, verander count met 1.","Change count by 1 means...":"Verander count met 1 betekent...","add 1 to what is in the box":"1 optellen bij wat er in de doos zit","put 1 in the box":"1 in de doos stoppen","empty the box":"de doos leegmaken","How will Bolt know it has seven gems? And what will you call the box?":"Hoe weet Bolt dat hij zeven edelstenen heeft? En hoe noem je de doos?","Pick a name a partner would understand, like count. Set it to 0, then change it by 1 for each gem.":"Kies een naam die een maatje begrijpt, zoals count. Zet hem op 0 en verander hem met 1 voor elke edelsteen.","The door opens when the box holds the true number of gems. The number changes each time.":"De deur gaat open als de doos het echte aantal edelstenen bevat. Het aantal verandert elke keer.","Count only when there really is a gem: if on a gem, pick and change count by 1.":"Tel alleen als er echt een edelsteen ligt: als op een edelsteen, oppakken en count veranderen met 1.","What is in the count box at the end?":"Wat zit er aan het eind in de doos count?","The number of gems Bolt picked up":"Het aantal edelstenen dat Bolt heeft opgepakt","Always 5":"Altijd 5","The number of moves":"Het aantal zetten","This door opens when the steps box reaches 0. Start high, count down.":"Deze deur gaat open als de doos steps 0 bereikt. Begin hoog en tel af.","Set steps to 4. Each time round, change steps by -1 before you move.":"Zet steps op 4. Verander steps elke ronde met -1 voordat je vooruit gaat.","Set empties the box and puts in a new number. Change...":"Zet maakt de doos leeg en stopt er een nieuw getal in. Verander...","adds to or takes from what is there":"telt erbij op of haalt eraf van wat erin zit","does the same as set":"doet hetzelfde als zet","deletes the box":"verwijdert de doos","Set steps to 6. Each time round, change steps by -1 before you move.":"Zet steps op 6. Verander steps elke ronde met -1 voordat je vooruit gaat.","This door opens after exactly two bumps. Who counts them?":"Deze deur gaat open na precies twee botsingen. Wie telt ze?","When bump: change bumps by 1 and turn right. The loop just moves.":"Wanneer Bolt botst: verander bumps met 1 en draai rechts. De lus gaat alleen vooruit.","The bumps box went up because...":"De doos bumps ging omhoog, omdat...","the when bump block changed it each time":"het blok wanneer Bolt botst hem elke keer veranderde","Bolt moved":"Bolt bewoog","it counts on its own":"hij vanzelf telt","Two boxes at once":"Twee dozen tegelijk","A program can keep many boxes. Here gems counts the gems and turns counts the corners. Each box has its own name, so you always know which is which.":"Een programma kan veel dozen hebben. Hier telt gems de edelstenen en turns de hoeken. Elke doos heeft een eigen naam, zodat je altijd weet welke welke is.","Two things to count: gems and turns. Two boxes.":"Twee dingen om te tellen: edelstenen en bochten. Twee dozen.","When bump: change turns by 1 and turn right. In the loop: if on a gem, pick and change gems by 1.":"Wanneer Bolt botst: verander turns met 1 en draai rechts. In de lus: als op een edelsteen, oppakken en gems veranderen met 1.","Why give each box its own name?":"Waarom geef je elke doos een eigen naam?","So you know which number is which":"Zodat je weet welk getal welk is","Boxes need names to exist":"Dozen bestaan alleen met een naam","Names make Bolt faster":"Namen maken Bolt sneller","Gems in different places, a corner, and a door that wants the true count.":"Edelstenen op verschillende plekken, een hoek en een deur die het echte aantal wil.","When bump: turn left. In the loop: if on a gem, pick and change count by 1. Then move.":"Wanneer Bolt botst: draai links. In de lus: als op een edelsteen, oppakken en count veranderen met 1. Dan vooruit.","A variable is useful when...":"Een variabele is handig als...","a number changes while the program runs":"een getal verandert terwijl het programma loopt","the number never changes":"het getal nooit verandert","there are no gems":"er geen edelstenen zijn","Three kinds of boxes":"Drie soorten dozen","The door reads a flag: hasKey must be on, and Bolt must really hold the key. When does the flag become true?":"De deur leest een schakelaar: hasKey moet aan staan, en Bolt moet de sleutel echt hebben. Wanneer wordt de schakelaar waar?","Set hasKey off at the start. When Bolt picks the key up, set hasKey on.":"Zet hasKey aan het begin op uit. Als Bolt de sleutel oppakt, zet hasKey op aan.","A flag variable holds...":"Een schakelaarvariabele bevat...","on or off":"aan of uit","any number":"elk getal","a picture":"een plaatje","The door shows the word it wants. Which box holds words?":"De deur laat het woord zien dat hij wil. Welke doos bevat woorden?","Set color to the word on the door, then drive.":"Zet color op het woord op de deur en rijd dan.","A word variable holds...":"Een woordvariabele bevat...","a word from a list":"een woord uit een lijst","a number":"een getal","This program works, but a partner cannot read it. What is x?":"Dit programma werkt, maar een maatje kan het niet lezen. Wat is x?","Tap a set or change block and give the box a name that says what it holds.":"Tik op een zet- of verander-blok en geef de doos een naam die zegt wat erin zit.","Rename x to count in every block that uses it.":"Hernoem x naar count in elk blok dat hem gebruikt.","Why is x a bad name here?":"Waarom is x hier een slechte naam?","It does not say what the box holds":"Hij zegt niet wat er in de doos zit","It is too long":"Hij is te lang","Letters are not allowed":"Letters zijn niet toegestaan","Bump! A wall after step {n}. Bolt did exactly what the blocks said.":"Boem! Een muur na stap {n}. Bolt deed precies wat de blokken zeiden.","The door is shut. What does it need before Bolt can go through?":"De deur is dicht. Wat heeft hij nodig voordat Bolt erdoor kan?","Splash! Bolt drove into the water after step {n}.":"Plons! Bolt reed na stap {n} het water in.","Bolt reached down after step {n}, but there was nothing to pick up there.":"Bolt wilde na stap {n} iets oppakken, maar daar lag niets.","One gem is still out there.":"Er ligt nog één edelsteen.","{n} gems are still out there.":{"one":"Er ligt nog {n} edelsteen.","other":"Er liggen nog {n} edelstenen."},"Bolt stopped, but not on the goal.":"Bolt is gestopt, maar niet op het doel.","The blocks call each other too deeply.":"De blokken roepen elkaar te diep aan.","{name} is not a clear name. A partner could not tell what is in that box.":"{name} is geen duidelijke naam. Een maatje zou niet weten wat er in die doos zit.","Split the route into named blocks first.":"Verdeel de route eerst in blokken met een naam.","A note chip does not match what its block does.":"Een notitie past niet bij wat het blok doet.","A block is called that was never made.":"Er wordt een blok aangeroepen dat nooit is gemaakt.","Something in the program is not a block Bolt knows.":"Iets in het programma is geen blok dat Bolt kent.","Two on one device":"Met z'n tweeën op één apparaat","Pair mode on: take turns driving.":"Duomodus aan: rijd om de beurt.","Pair mode off":"Duomodus uit","Daily Crew Challenge":"Dagelijkse teamuitdaging","One new board today":"Vandaag één nieuw speelveld","{n} Explorer stars":{"one":"{n} Ontdekkerster","other":"{n} Ontdekkersterren"},"{done}/{total} tasks":"{done}/{total} opdrachten","Crown":"Kroon","A friend tests your level":"Een vriend test je level","Swap! The navigator drives now.":"Wissel! Nu rijdt de navigator.","Driver":"Bestuurder","Navigator":"Navigator","Pair mode: player {n} drives":"Duomodus: speler {n} rijdt","Test {n}":"Test {n}","passed":"geslaagd","failed":"mislukt","Edits: {n}":"Wijzigingen: {n}","{n} edits from the starter program":{"one":"{n} wijziging ten opzichte van het startprogramma","other":"{n} wijzigingen ten opzichte van het startprogramma"},"Pick a route first: run both and choose one.":"Kies eerst een route: start ze allebei en kies er een.","Route {x}":"Route {x}","{n} blocks":{"one":"{n} blok","other":"{n} blokken"},"Run {x}":"{x} starten","Use {x}":"{x} gebruiken","Route {x} is in the program. Make it better, then run it.":"Route {x} staat in het programma. Maak hem beter en start hem dan.","Note chip":"Notitie","Credit line":"Bronregel","Use {p}":"{p} gebruiken","Takes a number: {p}":"Neemt een getal: {p}","What does {name} do?":"Wat doet {name}?","Stop":"Stop","Run":"Start","Make a block, then call it. Run wakes up when the program calls a block.":"Maak een blok en roep het dan aan. Start wordt wakker als het programma een blok aanroept.","Routes":"Routes","Back to the maker":"Terug naar de bouwer","Route {x} works: {n} blocks.":{"one":"Route {x} werkt: {n} blok.","other":"Route {x} werkt: {n} blokken."},"Route {x} fails. {why}":"Route {x} mislukt. {why}","Tested! Your friend solved it.":"Getest! Je vriend heeft het opgelost.","Level tested!":"Level getest!","Daily Crew Challenge done!":"Dagelijkse teamuitdaging klaar!","Build the flowchart":"Bouw het stroomschema","Tap the shapes in the order the chart runs them: boxes are actions, diamonds are questions. Then the shelf opens, and your blocks must follow the chart.":"Tik de vormen aan in de volgorde waarin het schema ze uitvoert: rechthoeken zijn acties, ruiten zijn vragen. Dan gaat de kast open, en je blokken moeten het schema volgen.","Task {n} of {total}":"Opdracht {n} van {total}","Your own level":"Je eigen level","Paint a board, press Check, then hand the device to a friend to test it.":"Verf een speelveld, druk op Controleren en geef het apparaat dan aan een vriend om te testen.","goal":"doel","gem":"edelsteen","key":"sleutel","Bolt":"Bolt","Square {x}, {y}: {what}":"Vakje {x}, {y}: {what}","{tile} tile":"tegel {tile}","Check":"Controleren","Test with a friend":"Testen met een vriend","Level code":"Levelcode","Save level":"Level opslaan","My levels":"Mijn levels","Enter a code":"Code invoeren","Clear board":"Speelveld leegmaken","Next task":"Volgende opdracht","The tasks":"De opdrachten","based on {code}":"gebaseerd op {code}","Four gems at most.":"Hoogstens vier edelstenen.","Level fixed!":"Level gerepareerd!","Task {n} done!":"Opdracht {n} klaar!","Now make your own!":"Maak nu je eigen level!","Plan it on paper, paint it, press Check, then hand the device to a friend to test it.":"Plan het op papier, verf het, druk op Controleren en geef het apparaat dan aan een vriend om te testen.","Press Check first: a level must be solvable before a friend tests it.":"Druk eerst op Controleren: een level moet oplosbaar zijn voordat een vriend het test.","Hand the device to your tester. Stay quiet and watch: say nothing until they are done.":"Geef het apparaat aan je tester. Wees stil en kijk: zeg niets tot hij klaar is.","Ready":"Klaar","Not now":"Niet nu","Read it out or write it on the board: a friend types it in with Enter a code on their device.":"Lees hem voor of schrijf hem op het bord: een vriend voert hem in met Code invoeren op zijn apparaat.","Place Bolt and the goal first. Then the board gets a code.":"Zet eerst Bolt en het doel neer. Dan krijgt het speelveld een code.","Open level":"Level openen","That code does not open a level. Check every symbol.":"Die code opent geen level. Controleer elk teken.","A remix: change the board, keep the based-on stamp, press Check.":"Een remix: verander het speelveld, houd de gebaseerd-op-stempel, druk op Controleren.","Level opened.":"Level geopend.","Saved. {n} levels in your box.":{"one":"Opgeslagen. {n} level in je doos.","other":"Opgeslagen. {n} levels in je doos."},"No saved levels yet. Press Save level in the maker.":"Nog geen opgeslagen levels. Druk in de bouwer op Level opslaan.","repeat until wall ahead":"herhaal tot muur vooruit","floor":"vloer","wall":"muur","water":"water","door":"deur","Picks up the gems":"Pakt de edelstenen op","Drives down the side":"Rijdt langs de zijkant naar beneden","Drives to the goal":"Rijdt naar het doel","Spins around on the spot":"Draait rond op zijn plek","Climbs a zigzag staircase":"Klimt een zigzagtrap op","Drives straight up":"Rijdt recht omhoog","based on Starter blocks":"gebaseerd op Startblokken","by the Robo Route team":"door het Robo Route-team","Place Bolt first.":"Zet eerst Bolt neer.","Place the goal flag.":"Zet de doelvlag neer.","A door needs a key, or gems to count.":"Een deur heeft een sleutel nodig, of edelstenen om te tellen.","No way to the goal. Open a path, or put the key before the door.":"Geen weg naar het doel. Maak een doorgang, of leg de sleutel voor de deur.","Solvable, but par is only {n}. Make it harder.":"Oplosbaar, maar de par is maar {n}. Maak het moeilijker.","Add a gem.":"Voeg een edelsteen toe.","Add a key.":"Voeg een sleutel toe.","Add a door.":"Voeg een deur toe.","Change at least {n} squares.":{"one":"Verander minstens {n} vakje.","other":"Verander minstens {n} vakjes."},"Solvable! Par {n}.":"Oplosbaar! Par {n}.","What should a player have to figure out on your board?":"Wat moet een speler op jouw speelveld uitzoeken?","Place Bolt and the goal first, then press Check. Walls and water make the route; gems and a key make a quest.":"Zet eerst Bolt en het doel neer en druk dan op Controleren. Muren en water vormen de route; edelstenen en een sleutel maken er een quest van.","A good first level: one corner, one gem, a par of six or more.":"Een goed eerste level: één hoek, één edelsteen, een par van zes of meer.","Count the squares, or let a loop count them.":"Tel de vakjes, of laat een lus ze tellen.","A corner needs a turn. A gem needs a pick up where Bolt stands.":"Een hoek heeft een bocht nodig. Een edelsteen heeft een oppakken nodig waar Bolt staat.","Drive to the first turn, turn, then drive again.":"Rijd naar de eerste bocht, draai en rijd dan weer verder.","What changes from day to day on this board? Bolt has to notice it as it drives.":"Wat verandert er van dag tot dag op dit speelveld? Bolt moet het merken tijdens het rijden.","Build the loop first, then put the if or when inside it.":"Bouw eerst de lus en zet dan de als of wanneer erin.","The corner is somewhere along the way. Let Bolt feel for it with an if.":"De hoek ligt ergens onderweg. Laat Bolt hem voelen met een als.","Paint marks the corners. Move, then ask: on paint?":"Verf markeert de hoeken. Ga vooruit en vraag dan: op verf?","A bump can be useful: catch it with a when block and turn.":"Botsen kan handig zijn: vang het op met een wanneer-blok en draai.","Pick up only when there is a gem under Bolt.":"Pak alleen op als er een edelsteen onder Bolt ligt.","One rule for every wall: if the path is clear move, else turn.":"Eén regel voor elke muur: als het pad vrij is vooruit, anders draaien.","The door wants the true number of gems in the count box.":"De deur wil het echte aantal edelstenen in de doos count.","Two questions every step: a gem here? a path ahead?":"Twee vragen bij elke stap: een edelsteen hier? een pad vrij?","Name a group of steps once, use it everywhere":"Geef een groep stappen één keer een naam en gebruik hem overal","A My Block is a group of steps with a name. Make it once; then a call block runs the whole group wherever you put it. Here the block Stair is already made for you: call it for every stair.":"Een Mijn blok is een groep stappen met een naam. Maak het één keer; dan voert een aanroep-blok de hele groep uit, waar je het ook zet. Hier is het blok Stair al voor je gemaakt: roep het aan voor elke tree.","The block Stair is already made. How do you run it?":"Het blok Stair is al gemaakt. Hoe voer je het uit?","Tap call on the shelf: one call runs everything inside Stair.":"Tik in de kast op roep aan: één aanroep voert alles in Stair uit.","A My Block is...":"Een Mijn blok is...","a group of steps with a name you can use again":"een groep stappen met een naam die je opnieuw kunt gebruiken","a kind of wall":"een soort muur","the goal flag":"de doelvlag","A procedure is a group of steps with a name. Define it once; a call runs the whole group. Three identical rooms, one block named Room: call it three times, then one more move to the goal.":"Een procedure is een groep stappen met een naam. Je legt hem één keer vast; een aanroep voert de hele groep uit. Drie gelijke kamers, één blok met de naam Room: roep het drie keer aan, en dan nog één keer vooruit naar het doel.","The block Room is already made. How do you run it?":"Het blok Room is al gemaakt. Hoe voer je het uit?","Tap call on the shelf: one call runs everything inside Room.":"Tik in de kast op roep aan: één aanroep voert alles in Room uit.","Bolt drives round three sides of a square. What is one side?":"Bolt rijdt langs drie zijden van een vierkant. Wat is één zijde?","The block Side is one side and a turn. After three calls Bolt still needs two moves.":"Het blok Side is één zijde en een bocht. Na drie aanroepen heeft Bolt nog twee keer vooruit nodig.","What does a call block do?":"Wat doet een aanroep-blok?","Runs all the steps inside the named block":"Het voert alle stappen in het blok met die naam uit","Deletes the block":"Het verwijdert het blok","Makes Bolt call for help":"Het laat Bolt om hulp roepen","Three sides of a big square. Make one block for a side.":"Drie zijden van een groot vierkant. Maak één blok voor een zijde.","Inside Side: repeat 5 with move, then turn right. Call it three times.":"In Side: herhaal 5 met vooruit, dan draai rechts. Roep het drie keer aan.","This route has two legs. What would you name each leg?":"Deze route heeft twee stukken. Hoe zou je elk stuk noemen?","Make one block for going up and one for going across. Then call both.":"Maak één blok voor omhoog en één voor oversteken. Roep ze dan allebei aan.","Why split a long route into named parts?":"Waarom verdeel je een lange route in stukken met een naam?","Each part is easier to check and to use again":"Elk stuk is makkelijker te controleren en opnieuw te gebruiken","Bolt drives faster":"Bolt rijdt sneller","You must use more blocks":"Je moet meer blokken gebruiken","A parameter: one block, many jobs":"Een parameter: één blok, veel klussen","These rooms have different depths. Instead of three blocks, make one block Room that takes a number: steps. Inside, repeat steps times. Each call gives its own number: Room(1), Room(3), Room(2).":"Deze kamers zijn verschillend diep. Maak in plaats van drie blokken één blok Room dat een getal neemt: steps. Herhaal daarin steps keer. Elke aanroep geeft zijn eigen getal mee: Room(1), Room(3), Room(2).","The rooms are 1, 3 and 2 deep. One block for all three?":"De kamers zijn 1, 3 en 2 diep. Eén blok voor alle drie?","Give Room a number, steps. Inside, repeat steps with move, both going in and coming back.":"Geef Room een getal, steps. Herhaal daarin steps keer vooruit, zowel heen als terug.","A parameter lets one block...":"Een parameter laat één blok...","do the same job with a different number each time":"dezelfde klus doen met elke keer een ander getal","run without being called":"werken zonder te worden aangeroepen","change the board":"het speelveld veranderen","Remix a starter block":"Remix een startblok","The Starter blocks shelf gives you blocks other people made. You may change them: that is a remix. Keep the line that says where the block came from, so everyone knows who started it.":"De kast Startblokken geeft je blokken die anderen hebben gemaakt. Je mag ze veranderen: dat is een remix. Houd de regel die zegt waar het blok vandaan komt, zodat iedereen weet wie ermee begonnen is.","Zig climbs one square, then steps across. These stairs are two squares tall.":"Zig klimt één vakje en stapt dan opzij. Deze treden zijn twee vakjes hoog.","Open Zig and add one more move at the start. Keep its credit line on.":"Open Zig en voeg aan het begin nog een vooruit toe. Laat de bronregel staan.","When you remix a block someone else made, you...":"Als je een blok remixt dat iemand anders heeft gemaakt, dan...","change it and keep the line saying where it came from":"verander je het en houd je de regel die zegt waar het vandaan komt","must never change it":"mag je het nooit veranderen","delete the credit line":"wis je de bronregel","Every straight run ends with a right turn. Only the length changes.":"Elk recht stuk eindigt met een bocht naar rechts. Alleen de lengte verandert.","Make Dash(n): repeat n move, then turn right. Call it with each length.":"Maak Dash(n): herhaal n keer vooruit, dan draai rechts. Roep het aan met elke lengte.","Dash(7) and Dash(3) run the same block with...":"Dash(7) en Dash(3) voeren hetzelfde blok uit met...","a different number":"een ander getal","a different robot":"een andere robot","no difference":"geen verschil","The starter blocks almost fit. Which one is one step short?":"De startblokken passen bijna. Welke is één stap te kort?","Dash is three moves; this corridor is four. Remix Dash, keep the credit line.":"Dash is drie keer vooruit; deze gang is vier lang. Remix Dash en houd de bronregel.","A remix is...":"Een remix is...","someone else's block, changed to fit a new job":"het blok van iemand anders, aangepast voor een nieuwe klus","a brand new block":"een gloednieuw blok","a mistake":"een fout","Three subgoals":"Drie deeldoelen","A big job is easier as three small ones: collect the gems, climb the stairs, cross to the goal. Make one block for each subgoal and give it a name that says what it does. Then the main program is just three calls.":"Een grote klus is makkelijker als drie kleine: de edelstenen verzamelen, de trap op klimmen, oversteken naar het doel. Maak een blok voor elk deeldoel en geef het een naam die zegt wat het doet. Dan is het hoofdprogramma maar drie aanroepen.","Name the three parts of this route before you build anything.":"Geef de drie stukken van deze route een naam voordat je iets bouwt.","One block collects the gems, one climbs, one crosses. The main program calls them in order.":"Eén blok verzamelt de edelstenen, één klimt, één steekt over. Het hoofdprogramma roept ze op volgorde aan.","Decomposition means...":"Opsplitsen betekent...","splitting a big problem into smaller parts":"een groot probleem in kleinere stukken verdelen","making the program longer":"het programma langer maken","deleting blocks":"blokken verwijderen","Three legs: up, across, down. Which leg has the gem?":"Drie stukken: omhoog, oversteken, omlaag. Welk stuk heeft de edelsteen?","Make a block for each leg. Across picks up the gem halfway.":"Maak een blok voor elk stuk. Oversteken pakt halverwege de edelsteen op.","Three named legs make a program...":"Drie stukken met een naam maken een programma...","easier to read and to fix":"makkelijker te lezen en te repareren","slower":"langzamer","impossible to run":"onmogelijk om uit te voeren","Document it":"Documenteer het","A note chip on a block tells a partner what the block does without reading every step. Pin the chip that matches each block: the level checks that your notes tell the truth.":"Een notitie op een blok vertelt een maatje wat het blok doet zonder elke stap te lezen. Plak bij elk blok de notitie die past: het level controleert of je notities de waarheid vertellen.","Three blocks, three jobs: along the top, down the side, home. Each needs a note chip.":"Drie blokken, drie klussen: bovenlangs, langs de zijkant omlaag, naar huis. Elk heeft een notitie nodig.","Open a block, tap Note chip and pick the sentence that says what it really does.":"Open een blok, tik op Notitie en kies de zin die zegt wat het echt doet.","A note chip on a block should say...":"Een notitie op een blok moet zeggen...","what the block does, truthfully":"wat het blok doet, eerlijk","how many stars you have":"hoeveel sterren je hebt","the name of the robot":"hoe de robot heet","The shelf block Zigzag was made by someone else. How many zigs does this staircase have?":"Het kastblok Zigzag is door iemand anders gemaakt. Hoeveel zigs heeft deze trap?","Call Zigzag with 5. Then make your own block for the last two squares, with its own note chip. Leave the credit line on Zigzag alone.":"Roep Zigzag aan met 5. Maak dan je eigen blok voor de laatste twee vakjes, met een eigen notitie. Laat de bronregel van Zigzag met rust.","When you use a block someone else made, the credit line...":"Als je een blok gebruikt dat iemand anders heeft gemaakt, dan blijft de bronregel...","stays on, so everyone knows who made it":"staan, zodat iedereen weet wie het heeft gemaakt","should be deleted":"niet staan, hij moet weg","makes Bolt slower":"staan en maakt Bolt langzamer","Expected and actual":"Verwacht en echt","This program has a bug. Press Step to run it one block at a time and watch where Bolt first does something you did not expect. Fix only that block: the fewest edits earn the most stars.":"Dit programma heeft een fout. Druk op Stap om het blok voor blok uit te voeren en kijk waar Bolt voor het eerst iets doet wat je niet verwachtte. Repareer alleen dat blok: de minste wijzigingen leveren de meeste sterren op.","Step through it. At which block does Bolt first go the wrong way?":"Loop er stap voor stap doorheen. Bij welk blok gaat Bolt voor het eerst de verkeerde kant op?","After three moves Bolt should turn toward the flag. Which way is that?":"Na drie keer vooruit moet Bolt naar de vlag draaien. Welke kant is dat?","Change the turn left into turn right.":"Verander de draai links in draai rechts.","A bug is...":"Een bug is...","a mistake in a program":"een fout in een programma","an insect on the board":"een insect op het speelveld","a kind of block":"een soort blok","Bolt bumps right at the end. One too many of what?":"Bolt botst helemaal aan het eind. Eén te veel van wat?","Count the squares between Bolt and the flag, then look at the repeat number.":"Tel de vakjes tussen Bolt en de vlag en kijk dan naar het herhaalgetal.","Change the repeat from 6 to 5.":"Verander de herhaal van 6 in 5.","Bolt bumped the wall one step after the flag. The bug is...":"Bolt botste één stap na de vlag tegen de muur. De fout is...","the loop runs one time too many":"de lus gaat één keer te vaak rond","the flag is in the wrong place":"de vlag staat op de verkeerde plek","move is broken":"vooruit is kapot","Bolt reached the flag but the level is not done. What is still on the board?":"Bolt is bij de vlag, maar het level is niet klaar. Wat ligt er nog op het speelveld?","Bolt drove over the gem. Which block is missing, and where?":"Bolt reed over de edelsteen heen. Welk blok mist er, en waar?","Add a pick up after the second move.":"Voeg na de tweede vooruit een oppakken toe.","Bolt finished on the flag but a gem was left. The fix is...":"Bolt eindigde op de vlag, maar er bleef een edelsteen liggen. De oplossing is...","add the missing block in the right place":"het ontbrekende blok op de goede plek toevoegen","delete everything and start again":"alles wissen en opnieuw beginnen","add more moves":"meer vooruit toevoegen","Bolt turns when it should move and moves when it should turn. Look at the question in the if.":"Bolt draait als hij vooruit moet en gaat vooruit als hij moet draaien. Kijk naar de vraag in de als.","The if asks wall ahead. What should it ask so that yes means move?":"De als vraagt muur vooruit. Wat moet hij vragen zodat ja vooruit betekent?","Change the condition from wall ahead to path ahead.":"Verander de voorwaarde van muur vooruit in pad vrij.","The program moved when it should have turned. The bug was in...":"Het programma ging vooruit toen het had moeten draaien. De fout zat in...","the condition of the if":"de voorwaarde van de als","the number of gems":"het aantal edelstenen","the color of Bolt":"de kleur van Bolt","All the right blocks are here. Is one of them in the wrong place?":"Alle goede blokken zijn er. Staat er een op de verkeerde plek?","Bolt turns too early. Move the turn right down one place.":"Bolt draait te vroeg. Schuif de draai rechts één plek omlaag.","Move the turn right so it comes after the second move.":"Verplaats de draai rechts zodat hij na de tweede vooruit komt.","Every block was right but the order was wrong. That is...":"Elk blok was goed, maar de volgorde was fout. Dat is...","still a bug: order matters":"toch een fout: volgorde telt","fine: order never matters":"prima: volgorde telt nooit","impossible":"onmogelijk","Step through one stair. Does Bolt end up facing the right way?":"Loop één tree stap voor stap door. Kijkt Bolt aan het eind de goede kant op?","There is one block too many inside the loop. Which one?":"Er zit één blok te veel in de lus. Welke?","Delete the second turn left inside the repeat.":"Verwijder de tweede draai links in de herhaal.","An extra block inside a loop...":"Een extra blok in een lus...","runs every time round, so it breaks every stair":"wordt elke ronde uitgevoerd, dus het verpest elke tree","does nothing":"doet niets","Two bugs this time. Watch the first gem: which way should Bolt turn?":"Deze keer twee fouten. Kijk naar de eerste edelsteen: welke kant moet Bolt op draaien?","The when block turns the wrong way. And is the loop long enough to reach the flag?":"Het wanneer-blok draait de verkeerde kant op. En is de lus lang genoeg om de vlag te halen?","Change left to right in the when block, and the repeat from 6 to 8.":"Verander links in rechts in het wanneer-blok, en de herhaal van 6 in 8.","After fixing one bug Bolt still fails. You should...":"Na het repareren van één fout mislukt Bolt nog steeds. Je moet...","test again and look for the next bug":"opnieuw testen en de volgende fout zoeken","give up":"opgeven","add random blocks":"willekeurige blokken toevoegen","Test cases":"Testgevallen","One program, three test boards. A fix must pass them all: the tabs above the board show a tick or a cross for each test after a run. Find the test that fails, step through it, and change as little as you can.":"Eén programma, drie testspeelvelden. Een reparatie moet ze allemaal halen: na een run laten de tabs boven het speelveld voor elke test een vinkje of een kruisje zien. Zoek de test die mislukt, loop er stap voor stap doorheen en verander zo weinig mogelijk.","Which test board fails? Run and read the tabs.":"Welk testspeelveld mislukt? Start en lees de tabs.","At the corner Bolt turns the wrong way on every board. Which turn is it?":"Bij de hoek draait Bolt op elk speelveld de verkeerde kant op. Welke bocht is het?","Change turn right to turn left in the else part.":"Verander in het anders-deel draai rechts in draai links.","Why test a program on more than one board?":"Waarom test je een programma op meer dan één speelveld?","A bug may only show on some inputs":"Een fout zie je misschien alleen bij sommige invoer","It makes the program longer":"Het maakt het programma langer","Bolt likes it":"Bolt vindt het leuk","Bolt reaches down on every square. What is wrong with that?":"Bolt grijpt op elk vakje naar beneden. Wat is daar fout aan?","Pick up only when there is a gem: wrap the pick in an if.":"Pak alleen op als er een edelsteen ligt: zet het oppakken in een als.","Put the pick up inside an if on a gem.":"Zet het oppakken in een als op een edelsteen.","Picking up where there is no gem is...":"Oppakken waar geen edelsteen ligt is...","an error the tests catch":"een fout die de tests vinden","always fine":"altijd prima","The door reads the count box. Watch the pill: does the box ever change?":"De deur leest de doos count. Kijk naar de meter: verandert de doos ooit?","Bolt picks gems but never counts them. Which block is missing inside the if?":"Bolt pakt edelstenen op maar telt ze nooit. Welk blok mist er in de als?","Add change count by 1 right after the pick up.":"Voeg direct na het oppakken verander count met 1 toe.","The watch pill never moved. That tells you...":"De meter bewoog nooit. Dat vertelt je...","the variable is never changed":"de variabele wordt nooit veranderd","the door is broken":"de deur is kapot","Bolt is slow":"Bolt is langzaam","Bolt turns right on a gem that is not at a corner. Read the first condition aloud.":"Bolt draait rechts op een edelsteen die niet op een hoek ligt. Lees de eerste voorwaarde hardop.","Wall ahead OR on a gem is true too often. Which word should join the two questions?":"Muur vooruit OF op een edelsteen is te vaak waar. Welk woord moet de twee vragen verbinden?","Change or to and in the first if.":"Verander of in en in de eerste als.","OR was true too often. AND is true only when...":"OF was te vaak waar. EN is alleen waar als...","both parts are true":"beide delen waar zijn","either part is true":"een van de delen waar is","Two boxes: gems and count. Which one does the door read?":"Twee dozen: gems en count. Welke leest de deur?","The program counts into the wrong box. Which block names count?":"Het programma telt in de verkeerde doos. Welk blok noemt count?","Change count by 1 should be change gems by 1.":"Verander count met 1 moet verander gems met 1 zijn.","The program counted into the wrong variable. The door...":"Het programma telde in de verkeerde variabele. De deur...","read a box that stayed at 0":"las een doos die op 0 bleef","opened anyway":"ging toch open","counted for itself":"telde zelf","Tests 1 and 2 pass. What is different about test 3?":"Test 1 en 2 slagen. Wat is er anders aan test 3?","Test 3 has no gems at all, so the count never reaches 2. When should the loop really stop?":"Test 3 heeft helemaal geen edelstenen, dus de telling komt nooit op 2. Wanneer moet de lus echt stoppen?","Change repeat until count = 2 into repeat until on the goal.":"Verander herhaal tot count = 2 in herhaal tot op het doel.","An edge case is...":"Een randgeval is...","an unusual input that breaks a hidden assumption":"een ongewone invoer die een verborgen aanname breekt","the border of the board":"de rand van het speelveld","a very long program":"een heel lang programma","Bolt reaches the goal on every board, but only by bumping into each corner. This level says: never bump.":"Bolt haalt op elk speelveld het doel, maar alleen door tegen elke hoek te botsen. Dit level zegt: nooit botsen.","Bolt only turns after a bump. Make it look before it moves: ask about the wall inside the loop.":"Bolt draait alleen na een botsing. Laat hem kijken voordat hij vooruit gaat: vraag in de lus naar de muur.","Inside the loop, before the move, add: if wall ahead, turn right.":"Voeg in de lus, voor de vooruit, toe: als muur vooruit, draai rechts.","Bolt reached the goal but bumped on the way. For this test that is...":"Bolt haalde het doel maar botste onderweg. Voor deze test is dat...","a fail: the rule was never bump":"mislukt: de regel was nooit botsen","a pass":"geslaagd","extra points":"extra punten","Two routes, one better":"Twee routes, één beter","Two programs can both reach the flag. Run each one and count: which is shorter, which has fewer blocks, which avoids trouble? Pick the better one, then make it better still.":"Twee programma's kunnen allebei de vlag halen. Start ze allebei en tel: welke is korter, welke heeft minder blokken, welke ontwijkt problemen? Kies de betere en maak hem nog beter.","Run both routes. Count the blocks in each.":"Start beide routes. Tel de blokken in elke route.","Route A goes up and across in seven blocks. Can a repeat make it shorter?":"Route A gaat in zeven blokken omhoog en opzij. Kan een herhaal hem korter maken?","Two programs both work. The better one is usually the one that...":"Twee programma's werken. De betere is meestal die...","does the job with fewer steps or blocks":"de klus klaart met minder stappen of blokken","has the most blocks":"de meeste blokken heeft","was written first":"als eerste is geschreven","Route A works but is long. Route B is short but bumps. Which is easier to fix?":"Route A werkt maar is lang. Route B is kort maar botst. Welke is makkelijker te repareren?","Route B turns one square too early. Fix its first repeat number.":"Route B draait één vakje te vroeg. Repareer het getal van zijn eerste herhaal.","A short program with one bug is often...":"Een kort programma met één fout is vaak...","the better start: fix the bug and keep it short":"het betere begin: repareer de fout en houd het kort","useless":"nutteloos","the same as a long one":"hetzelfde als een lang programma","Route A is short. Why does it not count?":"Route A is kort. Waarom telt hij niet?","Route B works but spins on the spot near the end. Which turns cancel each other?":"Route B werkt maar draait aan het eind rondjes op zijn plek. Welke bochten heffen elkaar op?","Delete the turn left and turn right that come right after each other.":"Verwijder de draai links en draai rechts die direct na elkaar komen.","The shortest program drove into the water. Shortest is best only if...":"Het kortste programma reed het water in. Het kortste is alleen het beste als...","it still works":"het toch werkt","it has a loop":"het een lus heeft","it has no turns":"het geen bochten heeft","Route B works with sixteen blocks. Route A has five but stops short.":"Route B werkt met zestien blokken. Route A heeft er vijf maar stopt te vroeg.","Count the stairs. Route A repeats one stair too few.":"Tel de treden. Route A herhaalt één tree te weinig.","Change Route A to repeat 4.":"Verander Route A in herhaal 4.","Compared to sixteen single blocks, a loop that does the same thing is...":"Vergeleken met zestien losse blokken is een lus die hetzelfde doet...","slower for Bolt":"langzamer voor Bolt","less exact":"minder precies","Route A reaches the flag quickly. Why is the level not done?":"Route A haalt snel de vlag. Waarom is het level niet klaar?","Route B picks up both gems. Which part of it repeats?":"Route B pakt beide edelstenen op. Welk deel ervan herhaalt zich?","Route A was fast but left the gems. Comparing routes means checking...":"Route A was snel maar liet de edelstenen liggen. Routes vergelijken betekent controleren...","that they do the whole job, then how well":"of ze de hele klus doen, en dan hoe goed","only the speed":"alleen de snelheid","only the number of turns":"alleen het aantal bochten","A flowchart is a plan with shapes":"Een stroomschema is een plan met vormen","Boxes are actions. Diamonds are questions with a yes way and a no way. Build the flowchart first by putting its tiles in order. Then your blocks must follow it exactly: the level checks the program against the chart.":"Rechthoeken zijn acties. Ruiten zijn vragen met een ja-weg en een nee-weg. Bouw eerst het stroomschema door de stukjes op volgorde te zetten. Dan moeten je blokken het precies volgen: het level vergelijkt het programma met het schema.","Follow the chart with your finger: what happens at the diamond?":"Volg het schema met je vinger: wat gebeurt er bij de ruit?","The chart says: until the goal, if path ahead then move, else turn right. Your blocks must say the same.":"Het schema zegt: tot het doel, als pad vrij dan vooruit, anders draai rechts. Je blokken moeten hetzelfde zeggen.","In a flowchart, a diamond is...":"In een stroomschema is een ruit...","a question with a yes way and a no way":"een vraag met een ja-weg en een nee-weg","an action":"een actie","the end":"het einde","Start":"Start","Is Bolt on the goal? Yes: stop":"Staat Bolt op het doel? Ja: stop","Is the path ahead clear?":"Is het pad vooruit vrij?","Yes: move forward":"Ja: ga vooruit","No: turn right":"Nee: draai rechts","Back to the top":"Terug naar boven","Two diamonds this time. Which question comes first in the chart?":"Deze keer twee ruiten. Welke vraag komt eerst in het schema?","First: if on a gem, pick up. Then: if path ahead move, else turn right.":"Eerst: als op een edelsteen, oppakken. Dan: als pad vrij vooruit, anders draai rechts.","Two diamonds in a row mean...":"Twee ruiten na elkaar betekenen...","two questions asked one after the other every time round":"twee vragen die elke ronde na elkaar worden gesteld","one question asked twice":"één vraag die twee keer wordt gesteld","the chart is broken":"het schema is kapot","Is there a gem here? Yes: pick it up":"Ligt hier een edelsteen? Ja: pak hem op","The chart has a side branch that starts with When. Which block is that?":"Het schema heeft een zijtak die begint met Wanneer. Welk blok is dat?","When Bolt bumps, turn left. The main loop just moves until the goal.":"Wanneer Bolt botst, draai links. De hoofdlus gaat gewoon vooruit tot het doel.","A When branch in the chart runs...":"Een Wanneer-tak in het schema wordt uitgevoerd...","whenever its event happens, wherever the main loop is":"telkens als zijn gebeurtenis plaatsvindt, waar de hoofdlus ook is","only at the end":"alleen aan het eind","When Bolt bumps: turn left":"Wanneer Bolt botst: draai links","Move forward":"Ga vooruit","Now the hallway is two squares longer":"Nu is de gang twee vakjes langer","A program that counts squares breaks when the hallway grows. Test 2 is the same level with a longer hallway. Follow the flowchart: drive until the wall, turn, drive until the goal. Then both tests pass.":"Een programma dat vakjes telt, gaat kapot als de gang langer wordt. Test 2 is hetzelfde level met een langere gang. Volg het stroomschema: rijd tot de muur, draai, rijd tot het doel. Dan slagen beide tests.","The old program passes test 1. Run test 2. What changed?":"Het oude programma haalt test 1. Start test 2. Wat is er veranderd?","Counting four moves only fits the short hallway. The chart says drive until the wall.":"Vier keer vooruit tellen past alleen bij de korte gang. Het schema zegt: rijd tot de muur.","A program that passes test 1 and fails test 2...":"Een programma dat test 1 haalt en test 2 niet...","is not finished yet":"is nog niet klaar","is finished":"is klaar","needs more moves":"heeft meer vooruit nodig","Is there a wall ahead? No: move forward and ask again":"Is er een muur vooruit? Nee: ga vooruit en vraag opnieuw","Yes: turn left":"Ja: draai links","Is Bolt on the goal? No: move forward and ask again":"Staat Bolt op het doel? Nee: ga vooruit en vraag opnieuw","Yes: stop":"Ja: stop","Three tests: the corner and the gems move. Only a chart-shaped program passes all three.":"Drie tests: de hoek en de edelstenen verschuiven. Alleen een programma in de vorm van het schema haalt ze alle drie.","Pick up if on a gem. Then: if path ahead move, else turn left.":"Oppakken als op een edelsteen. Dan: als pad vrij vooruit, anders draai links.","The same program passed three different boards because...":"Hetzelfde programma haalde drie verschillende speelvelden, omdat...","it asked questions instead of counting":"het vragen stelde in plaats van te tellen","the boards were the same":"de speelvelden hetzelfde waren","No: turn left":"Nee: draai links","Plan, build, test, improve":"Plannen, bouwen, testen, verbeteren","In the Level Maker you paint the board: pick a tile, tap a square. Check proves a level can be solved and tells you its par. Test with a friend hands the device over. Nothing is typed: a level code carries the whole board.":"In de Levelbouwer verf je het speelveld: kies een tegel en tik op een vakje. Controleren bewijst dat een level oplosbaar is en vertelt je de par. Testen met een vriend geeft het apparaat door. Er wordt niets getypt: een levelcode bevat het hele speelveld.","Where is the goal? Which squares around it are walls?":"Waar is het doel? Welke vakjes eromheen zijn muren?","Pick the floor tile and tap one wall next to the goal that touches the corridor.":"Kies de vloertegel en tik op een muur naast het doel die aan de gang grenst.","Tap the wall on the left of the goal, then press Check.":"Tik op de muur links van het doel en druk dan op Controleren.","Check turns red and says no way to the goal. That means...":"Controleren wordt rood en zegt dat er geen weg naar het doel is. Dat betekent...","no program could ever solve the level":"geen enkel programma kan het level ooit oplossen","the level is hard":"het level is moeilijk","Bolt is tired":"Bolt is moe","The goal is walled in. Open one wall so Bolt can reach it, then press Check.":"Het doel is ommuurd. Maak een muur open zodat Bolt erbij kan en druk dan op Controleren.","Pick the floor tile and open a way from the corridor to the goal.":"Kies de vloertegel en maak een weg van de gang naar het doel.","Open the two walls between the corridor and the goal, then press Check.":"Maak de twee muren tussen de gang en het doel open en druk dan op Controleren.","The goal is walled in. Open walls so Bolt can reach it, then press Check.":"Het doel is ommuurd. Maak muren open zodat Bolt erbij kan en druk dan op Controleren.","Par is the fewest commands a perfect program needs. How do you make Bolt work harder?":"De par is het kleinste aantal opdrachten dat een perfect programma nodig heeft. Hoe laat je Bolt harder werken?","Move the goal to the far corner, or put walls in the straight way.":"Zet het doel in de verste hoek, of zet muren op de rechte weg.","Put the goal in the bottom corner and a wall in the middle, then press Check.":"Zet het doel in de onderste hoek en een muur in het midden en druk dan op Controleren.","Too easy: par is 1. Move the goal or add walls until par is at least 6. Keep it solvable.":"Te makkelijk: de par is 1. Verplaats het doel of voeg muren toe tot de par minstens 6 is. Houd het oplosbaar.","Move the goal far away and put a wall across the straight way.":"Zet het doel ver weg en een muur dwars over de rechte weg.","Put the goal in the bottom corner and a long wall in the middle, then press Check.":"Zet het doel in de onderste hoek en een lange muur in het midden en druk dan op Controleren.","Too easy: par is 1. Move the goal or add walls until par is at least 10. Keep it solvable.":"Te makkelijk: de par is 1. Verplaats het doel of voeg muren toe tot de par minstens 10 is. Houd het oplosbaar.","A door only opens for a key. Where must the key be?":"Een deur gaat alleen open met een sleutel. Waar moet de sleutel liggen?","Put the key before the door on the way, and a gem anywhere Bolt can reach.":"Leg de sleutel op de weg voor de deur, en een edelsteen ergens waar Bolt kan komen.","Gem next to Bolt, key on the left side, door right before the goal. Then Check.":"Edelsteen naast Bolt, sleutel aan de linkerkant, deur vlak voor het doel. Dan Controleren.","unsolvable: Check will refuse it":"onoplosbaar: Controleren weigert het","harder":"moeilijker","Make it a quest: add a gem, a key and a door on the way to the goal. Keep it solvable.":"Maak er een quest van: voeg op weg naar het doel een edelsteen, een sleutel en een deur toe. Houd het oplosbaar.","A remix keeps the based-on stamp and changes something real.":"Een remix houdt de gebaseerd-op-stempel en verandert iets echts.","Add gems, a puddle or a wall: three squares or more. Then Check.":"Voeg edelstenen, een plas of een muur toe: drie vakjes of meer. Dan Controleren.","Put two gems on the way and a puddle in the bottom row, then press Check.":"Leg twee edelstenen op de weg en een plas in de onderste rij en druk dan op Controleren.","The based-on stamp on a remixed level...":"De gebaseerd-op-stempel op een geremixt level...","credits the level it came from":"noemt het level waar het vandaan komt","makes it harder":"maakt het moeilijker","is the par":"is de par","Remix: this level came from a code. Change at least three squares, keep it solvable, and keep the based-on stamp.":"Remix: dit level komt uit een code. Verander minstens drie vakjes, houd het oplosbaar en houd de gebaseerd-op-stempel.","Add a note chip to {name}: what does that block do?":"Voeg een notitie toe aan {name}: wat doet dat blok?","Keep the block {name} and its credit line: it says where the block came from.":"Houd het blok {name} en zijn bronregel: die zegt waar het blok vandaan komt.","Remix means change something. {name} is still exactly the starter block.":"Remixen betekent iets veranderen. {name} is nog precies het startblok.","The program does not follow the flowchart. Check each box and diamond against your blocks.":"Het programma volgt het stroomschema niet. Vergelijk elke rechthoek en elke ruit met je blokken.","Door: {rule}":"Deur: {rule}","Blocks":"Blokken","A when block goes at the top of the program.":"Een wanneer-blok hoort bovenaan in het programma.","A My Block goes at the top of the program.":"Een Mijn blok hoort bovenaan in het programma.","Move into the else part":"In het anders-deel zetten","Wrap the blocks below":"De blokken eronder omsluiten","First question":"Eerste vraag","Second question":"Tweede vraag","Hints open after two tries at Pro: one more run.":"Bij Pro gaan de hints open na twee pogingen: nog één run.","Run your program first. Hints open after two tries at Pro.":"Start eerst je programma. Bij Pro gaan de hints open na twee pogingen.","Keyboard: 1 to 8 add a block, Delete removes it, R or Ctrl+Enter runs.":"Toetsenbord: 1 tot 8 voegen een blok toe, Delete haalt het weg, R of Ctrl+Enter start.","Tiles":"Tegels","Skip task":"Opdracht overslaan","Task skipped":"Opdracht overgeslagen","What did your tester say?":"Wat zei je tester?","One fun thing:":"Iets leuks:","The route":"De route","The gems":"De edelstenen","The tricky corner":"De lastige hoek","The door":"De deur","One confusing thing:":"Iets verwarrends:","Too easy":"Te makkelijk","Too hard":"Te moeilijk","A dead end":"Een doodlopende weg","Nothing":"Niets","Change one thing, then press Check again":"Verander één ding en druk dan weer op Controleren","Improved after a test":"Verbeterd na een test","a repeat block":"een herhaal-blok","a repeat inside a repeat":"een herhaal in een herhaal","an if block":"een als-blok","a when block":"een wanneer-blok","a call block":"een aanroep-blok","a My Block":"een Mijn blok","a set block":"een zet-blok","a change block":"een verander-blok","Start with the moves that reach the turn, then one turn left block.":"Begin met de vooruit-zetten tot de bocht, dan één blok draai links.","Drive onto the gem first and add a pick up there. The turn comes later.":"Rijd eerst op de edelsteen en zet daar een oppakken. De bocht komt later.","The first leg is two moves, then pick up. Build that, then think about the turn.":"Het eerste stuk is twee keer vooruit, dan oppakken. Bouw dat en denk dan aan de bocht.","Line 1 is four moves and a pick up. Build that leg first, then run it.":"Regel 1 is vier keer vooruit en een oppakken. Bouw eerst dat stuk en start het dan.","Drive two squares first, then turn left to face the gap.":"Rijd eerst twee vakjes en draai dan links naar de opening.","The first leg is five moves. Then one turn right.":"Het eerste stuk is vijf keer vooruit. Dan één keer draai rechts.","Drive back west":"Rijd terug naar het westen","Go down to the goal":"Ga naar beneden naar het doel","Start with turn right: the shorter route goes down the left side first.":"Begin met draai rechts: de kortere route gaat eerst langs de linkerkant naar beneden.","Start with turn right: the route down the left side is the shorter one.":"Begin met draai rechts: de route langs de linkerkant is de kortere.","Leg 1 is three moves to the gem, then pick up.":"Stuk 1 is drie keer vooruit naar de edelsteen, dan oppakken.","Leg 1 is four moves to the gem, then pick up.":"Stuk 1 is vier keer vooruit naar de edelsteen, dan oppakken.","Tap repeat first, then move: the move lands inside the repeat.":"Tik eerst op herhaal en dan op vooruit: de vooruit komt in de herhaal terecht.","Put one stair inside a repeat and count the stairs for its number.":"Zet één tree in een herhaal en tel de treden voor het getal.","Put one side inside the repeat: the moves along it, then the turn.":"Zet één zijde in de herhaal: de vooruit-zetten erlangs, dan de bocht.","Move then pick up inside the repeat: one pair per gem.":"Vooruit en dan oppakken in de herhaal: één paar per edelsteen.","One side is three moves, pick up, turn right. Put that inside the repeat.":"Eén zijde is drie keer vooruit, oppakken, draai rechts. Zet dat in de herhaal.","Put one zig inside the repeat and set its number to the number of zigs.":"Zet één zig in de herhaal en stel het getal in op het aantal zigs.","Put one stair inside the repeat and count the stairs for its number.":"Zet één tree in de herhaal en tel de treden voor het getal.","Inside the outer repeat, start with repeat 2 holding one move: that is the up part of a stair.":"Begin in de buitenste herhaal met herhaal 2 met één vooruit: dat is het stuk omhoog van een tree.","Start with the inner part: repeat 3 with move and pick up clears one row.":"Begin met het binnenste deel: herhaal 3 met vooruit en oppakken maakt één rij leeg.","The inner loop is repeat 2 with move and pick up: that climbs one stair.":"De binnenste lus is herhaal 2 met vooruit en oppakken: die klimt één tree.","One side is repeat 3 with move. Put that and a turn right inside an outer repeat.":"Eén zijde is herhaal 3 met vooruit. Zet dat en een draai rechts in een buitenste herhaal.","Put the if / else block inside the repeat. Move goes in the if part.":"Zet het blok als / anders in de herhaal. Vooruit hoort in het als-deel.","Put turn right inside the when gem block.":"Zet draai rechts in het blok wanneer een edelsteen is opgepakt.","Inside repeat until goal, put an if / else with move in the if part.":"Zet in herhaal tot doel een als / anders met vooruit in het als-deel.","Inside the loop: move first, then an if on paint block.":"In de lus: eerst vooruit, dan een blok als op verf.","Put turn left inside the when bump block.":"Zet draai links in het blok wanneer Bolt botst.","Put pick up inside an if on a gem block, then one move after it.":"Zet oppakken in een blok als op een edelsteen, en daarna één vooruit.","Make the first if ask two things: wall ahead and on a gem.":"Laat de eerste als twee dingen vragen: muur vooruit en op een edelsteen.","Build the question first: not path ahead, then or, then on paint.":"Bouw eerst de vraag: niet pad vrij, dan of, dan op verf.","Start the loop with an if something to pick up block holding pick up.":"Begin de lus met een blok als iets om op te pakken met oppakken erin.","A variable is a box with a name. Set puts a number in the box. Change by adds to it. The watch pill shows what is inside right now. This door opens only when the count box says the number written on the door.":"Een variabele is een doos met een naam. Zet stopt een getal in de doos. Verander met telt erbij op. De meter laat zien wat er nu in zit. Deze deur gaat alleen open als de doos count het getal laat zien dat op de deur staat.","Put change count by 1 right after the pick up inside the repeat.":"Zet verander count met 1 direct na het oppakken, in de herhaal.","Name the box count, then put change count by 1 right after the pick up.":"Noem de doos count en zet dan verander count met 1 direct na het oppakken.","Inside the if on a gem block: pick up, then change count by 1.":"In het blok als op een edelsteen: oppakken, dan verander count met 1.","Set steps to the number of squares before the door, then change it by -1 inside the loop.":"Zet steps op het aantal vakjes voor de deur en verander het dan met -1 in de lus.","Put change bumps by 1 inside the when bump block, before the turn.":"Zet verander bumps met 1 in het blok wanneer Bolt botst, voor de bocht.","Set both boxes to 0 first. Then change gems by 1 goes right after the pick up.":"Zet eerst beide dozen op 0. Daarna komt verander gems met 1 direct na het oppakken.","Put change count by 1 right after the pick up, inside the if on a gem block.":"Zet verander count met 1 direct na het oppakken, in het blok als op een edelsteen.","Right after the pick up, add set hasKey to on.":"Voeg direct na het oppakken zet hasKey op aan toe.","Start with a set block: color gets the word written on the door.":"Begin met een zet-blok: color krijgt het woord dat op de deur staat.","Add one call Stair block and run it: Bolt climbs one stair.":"Voeg één blok roep Stair aan toe en start het: Bolt klimt één tree.","Add one call Room block and run it: Bolt clears one room.":"Voeg één blok roep Room aan toe en start het: Bolt maakt één kamer leeg.","Add call Side once and watch what one call does.":"Voeg één keer roep Side aan toe en kijk wat één aanroep doet.","Make My Block Side first: one side is a repeat with move inside, then a turn right.":"Maak eerst Mijn blok Side: één zijde is een herhaal met vooruit erin, dan een draai rechts.","Make My Block Up with four moves inside, then call it.":"Maak Mijn blok Up met vier keer vooruit erin en roep het dan aan.","Give Room a number: tap the block, choose Takes a number, then use steps in its repeat.":"Geef Room een getal: tik op het blok, kies Neemt een getal en gebruik dan steps in zijn herhaal.","After the remix, call Zig twice: one call per stair.":"Roep na de remix Zig twee keer aan: één aanroep per tree.","Inside Dash, set the repeat to Use n. Then call Dash with 7 for the first run.":"Zet in Dash de herhaal op n gebruiken. Roep Dash dan aan met 7 voor het eerste stuk.","Add one more move to Dash, then start the program with call Dash.":"Voeg nog één vooruit toe aan Dash en begin het programma dan met roep Dash aan.","Make the first block GetGems: a repeat with move and pick up inside.":"Maak van het eerste blok GetGems: een herhaal met vooruit en oppakken erin.","Sweep drives along the top collecting gems, so its chip is Picks up the gems.":"Sweep rijdt bovenlangs en verzamelt edelstenen, dus zijn notitie is Pakt de edelstenen op.","Start with call Zigzag and set its number to the number of zigs.":"Begin met roep Zigzag aan en stel het getal in op het aantal zigs.","Put the first three moves of Route A inside one repeat.":"Zet de eerste drie vooruit-zetten van Route A in één herhaal.","Change the first repeat of Route B from 3 to 4.":"Verander de eerste herhaal van Route B van 3 in 4.","Put the first gem trip of Route B (two moves and a pick up) inside a repeat.":"Zet de eerste tocht naar een edelsteen van Route B (twee keer vooruit en een oppakken) in een herhaal.","The diamond is an if / else inside repeat until goal. Move goes in the if part.":"De ruit is een als / anders in herhaal tot doel. Vooruit hoort in het als-deel.","The first diamond is an if on a gem block holding pick up.":"De eerste ruit is een blok als op een edelsteen met oppakken erin.","The side branch is a when bump block: put turn left inside it.":"De zijtak is een blok wanneer Bolt botst: zet draai links erin.","Replace repeat 4 with repeat until wall ahead.":"Vervang herhaal 4 door herhaal tot muur vooruit.","Bolt ran out of energy: the program goes on and on. Is a loop going round and round?":"Bolt heeft geen energie meer: het programma gaat maar door. Draait er een lus rondjes?","This level needs {block}. The learn card shows how.":"Dit level heeft {block} nodig. De leerkaart laat zien hoe.","Use the shared block {name}: call it from your program.":"Gebruik het gedeelde blok {name}: roep het aan vanuit je programma.","Quest code":"Questcode","Type the four digits from your teacher":"Typ de vier cijfers van je leraar","Blocks: {n} · goal {max} or fewer":"Blokken: {n} · doel {max} of minder","Add after this block":"Toevoegen na dit blok","Fix it in {n} edits or fewer for the next star.":"Repareer het in {n} wijzigingen of minder voor de volgende ster.","Use {n} blocks or fewer for the next star.":"Gebruik {n} blokken of minder voor de volgende ster.","Solve it without the third hint for the next star.":"Los het op zonder de derde hint voor de volgende ster.","Chapter: {n} stars":"Hoofdstuksterren: {n}","{n} of {all} stars":"{n} van de {all} sterren","{ok} of {n} checks right":"{ok} van de {n} vragen goed","Back to class":"Terug naar de klas","All done. Your teacher can see your stars now.":"Alles klaar. Je leraar kan je sterren nu zien.","Play again":"Opnieuw spelen","No band has that number.":"Geen niveau heeft dat nummer.","How many squares does Bolt move to reach the flag?":"Hoeveel vakjes gaat Bolt vooruit om bij de vlag te komen?","The numbers on the floor count the squares. The flag square counts too.":"De getallen op de vloer tellen de vakjes. Het vlagvakje telt ook mee.","Use one move block for each square, up to and including the flag square.":"Gebruik één vooruit-blok per vakje, tot en met het vlagvakje.","Count the squares from Bolt to the flag. The flag square counts too.":"Tel de vakjes van Bolt tot de vlag. Het vlagvakje telt ook mee.","Put a pick up block right after the second move inside the repeat.":"Zet een oppakken-blok direct na de tweede vooruit, in de herhaal.","An if block asks a question about the world: is the path ahead clear? If yes, the blocks inside run. If no, the else blocks run. The program checks again every time.":"Een als-blok stelt een vraag over de wereld: is het pad vooruit vrij? Zo ja, dan worden de blokken erin uitgevoerd. Zo nee, dan de anders-blokken. Het programma controleert het elke keer opnieuw.","A number box holds a count. A flag box is a true/false (Boolean) box: on or off, like hasKey. A word box holds a word from a list, like color. Pick the kind that fits what you store.":"Een getaldoos bevat een aantal. Een schakelaardoos is een waar/onwaar-doos (booleaans): aan of uit, zoals hasKey. Een woorddoos bevat een woord uit een lijst, zoals color. Kies de soort die past bij wat je bewaart.","A procedure is...":"Een procedure is...","Your tester said the level was too easy. A good next step is...":"Je tester zei dat het level te makkelijk was. Een goede volgende stap is...","change the level using what they said, then test again":"het level veranderen met wat hij zei en dan opnieuw testen","tell them they played it wrong":"zeggen dat hij het verkeerd speelde","start a new level and never test it":"een nieuw level beginnen en het nooit testen","A level with a door, no key and no gems is...":"Een level met een deur, zonder sleutel en zonder edelstenen is...","Clear program":"Programma wissen","Start over":"Opnieuw beginnen","Undo":"Ongedaan maken"}} });
